def sky_rosters(extract):
 s=re.sub(r'^L\d+:\s?','',extract,flags=re.M);s=re.sub(r'【\d+†([^】]+)】',r'\1',s);rosters=[]
 for m in re.finditer(r'^#### ([^\n]+)\n(.*?)(?=^#### |\Z)',s,re.M|re.S):
  title,b=m.groups();cut=re.split(r'^##### (?:Substitutes|Reservebank)',b,flags=re.M)
  def players(t):
   ls=[x.strip() for x in t.splitlines() if x.strip()];return [dict(shirt=int(x),name=ls[i+1]) for i,x in enumerate(ls[:-1]) if x.isdigit() and not ls[i+1].startswith('*')]
  xi=players(cut[0]);bench=players(cut[1]) if len(cut)>1 else []
  if xi:rosters.append(dict(team_label=title,starters=xi,bench=bench))
 return rosters

